import { create_list_edit_phases } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    phasedeletion: Boolean,
    projData: Object
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    phasedeletion: {
      async handler() {
        if (this.phasedeletion == true) {}
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      let Projecctdetails = JSON.parse(localStorage.getItem("projectInfo"));
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_phases, {
          input: {
            project_id: Projecctdetails.project_id,
            phase_id: this.projData.phase_id,
            action_type: "DELETE",
            phase_status: "DEACTIVE"
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.create_list_edit_phases);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
